/*
 * ESP32-2432S028 Bluetooth Mouse
 *
 * When the ESP32 receives the character '1' over USB serial,
 * it sends one left mouse click over Bluetooth.
 *
 * Required library:
 *   ESP32-BLE-Mouse
 */

#include <Arduino.h>
#include <BleMouse.h>

BleMouse bleMouse("Prefire ESP32", "Prefire", 100);

void setup()
{
    Serial.begin(115200);

    bleMouse.begin();

    Serial.println("Prefire ESP32 mouse ready.");
    Serial.println("Connect to 'Prefire ESP32' over Bluetooth.");
}

void loop()
{
    if (bleMouse.isConnected())
    {
        if (Serial.available() > 0)
        {
            char command = Serial.read();

            if (command == '1')
            {
                bleMouse.click(MOUSE_LEFT);
                Serial.println("Click sent.");
            }
        }
    }

    delay(1);
}
